def transforms(S):
 out=[]
 for k in range(4):
  pts=set(S)
  for _ in range(k): pts={(c,-r) for r,c in pts}
  for refl in [False,True]:
   p={(r,-c if refl else c) for r,c in pts}
   mr=min(r for r,c in p); mc=min(c for r,c in p)
   p={(r-mr,c-mc) for r,c in p}
   out.append(p)
 return out
